import math

def summarize(completion_latencies, elapsed_seconds):
    if not completion_latencies or elapsed_seconds <= 0:
        raise ValueError("실제로 완료된 표본과 양의 측정 시간이 필요합니다")
    ordered = sorted(completion_latencies)
    def percentile(p):
        return ordered[max(0, math.ceil(len(ordered) * p) - 1)]
    return {
        "completed": len(ordered),
        "throughput_per_sec": len(ordered) / elapsed_seconds,
        "p50_sec": percentile(0.50),
        "p95_sec": percentile(0.95),
    }

import os
from celery import Celery

app = Celery("messageflow", broker=os.environ["BROKER_URL"],
             backend=os.environ["RESULT_BACKEND"])
app.conf.update(task_serializer="json", result_serializer="json",
                accept_content=["json"], task_track_started=True)

@app.task(name="lab.add")
def add(x: int, y: int):
    return x + y

# API에서 호출합니다. add 본문을 여기서 실행하지 않습니다.
def submit_add(x, y):
    job = add.apply_async(args=[x, y], queue="phase9.tasks")
    return {"task_id": job.id}

def lookup(task_id):
    job = app.AsyncResult(task_id)
    return {"state": job.state,
            "result": job.result if job.successful() else None}

# app은 Phase 9에서 구성한 Celery 앱
app.conf.task_routes = {"lab.flaky": {"queue": "phase10.slow"}}

@app.task(bind=True, name="lab.flaky", max_retries=3,
          acks_late=True, reject_on_worker_lost=True)
def flaky(self, failures_before_success=2):
    if self.request.retries < failures_before_success:
        delay = min(2 ** self.request.retries, 30)
        raise self.retry(exc=ConnectionError("학습용 일시 오류"), countdown=delay)
    return {"attempt_number": self.request.retries + 1, "status": "ok"}

import Pyro5.api

@Pyro5.api.expose
class Calculator:
    def add(self, x, y):
        return x + y

with Pyro5.api.Daemon(host="0.0.0.0", port=9090) as daemon:
    uri = daemon.register(Calculator(), objectId="calculator")
    print(uri)
    daemon.requestLoop()

import Pyro5.api
import Pyro5.errors

def rpc_add(x, y):
    with Pyro5.api.Proxy("PYRO:calculator@pyro-service:9090") as proxy:
        proxy._pyroTimeout = 3
        try:
            return {"result": proxy.add(x, y)}
        except Pyro5.errors.TimeoutError:
            return {"outcome": "TIMEOUT", "server_cancelled": False}
